\title[The hint extends beyond degree five]{The Hint Extends Beyond Degree Five:\\ Exact Hint Values and a CRT Defect Law\\ for Cyclic Splitting-Type Channels}
\author{Aristotle}
\date{September 2026}

\begin{document}

\begin{abstract}
Let $N=pq$ be a product of two primes and let $K$ be a cyclic number field of degree $n$ and prime conductor $f$. The \emph{hint value} of $K$ measures how much more the factor residues $(p \bmod f, q\bmod f)$ reveal about the unordered pair of residue degrees $\{f_K(p),f_K(q)\}$ than the product residue $N\bmod f$ reveals. We compute it exactly for the real sextic field $\Q(\zeta_{13})^+$ (Galois group $C_6$, conductor $13$). A numerical experiment had estimated $+1.6407$ bits; the exact value is $\log_2 3+\tfrac1{18}\approx 1.64052$ bits. The product view carries exactly $\log_2 3-\tfrac19$ bits and the joint residue view exactly $2\log_2 3-\tfrac1{18}$ bits. The sum dial and the gap dial each carry the entire hint; for the gap dial this uses the reality of the field. Hence the hint synergy lies exactly on the redundancy floor. The field-level value coincides with an abstract \emph{hint map} $h(n)$: the conditional entropy of the unordered pair of orders of two uniform elements of $\Z/n$, given their sum. Our main theorem is a general \emph{CRT defect law}: for coprime $m,n$,
\[
h(mn)=h(m)+h(n)+\delta(m)\delta(n),\qquad \delta(n)=1-\frac1{n^2}\sum_{d\mid n}\varphi(d)^2,
\]
where $\delta(n)$ is the probability that two uniform elements of $\Z/n$ have different orders. So the hint map is strictly superadditive over coprime non-trivial factors. The proof rests on an \emph{unordered-pair entropy law}, $H(\{X,Y\})=H(X,Y)-\Pr(X\neq Y)$ for i.i.d.\ $X,Y$. As a by-product we obtain an information-theoretic proof that $n\mapsto\sum_{d\mid n}\varphi(d)^2$ is multiplicative.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{The information battery}
A recurring experimental design asks how much a cheap, public observation of a semiprime reveals about arithmetic features of its hidden factors, compared with an expensive, private observation. In our setting:
\begin{itemize}
\item the \emph{hidden label} is the unordered pair of splitting types (residue degrees) of the prime factors $p,q$ of $N=pq$ in a fixed abelian field $K$;
\item the \emph{product view} is $N\bmod f$, where $f$ is the conductor of $K$;
\item the \emph{factor view} is $(p\bmod f,q\bmod f)$, or equivalently, for odd $f$, the pair $(s,d)=(p+q,p-q)\bmod f$.
\end{itemize}
The \emph{hint value} is the mutual information of the label with the factor view minus its mutual information with the product view. Earlier rounds of the experiment worked in fields of degree at most $5$. Round~31 was the first to reach degree $6$, with $\Q(\zeta_{13})^+$, and reported a product view of $1.4704$ bits, a joint residue view of $3.1110$ bits and a hint value of $+1.6407$ bits, together with the verdicts ``walls clean'' and ``the hint map extends beyond degree~5''.

\subsection{Summary of results}
\begin{enumerate}
\item Exact round-31 values (Theorem~\ref{thm:table}): $\log_2 3-\tfrac19$, $2\log_2 3-\tfrac1{18}$ and $\log_2 3+\tfrac1{18}$. The reported figures are finite-sample estimates.
\item Maximal redundancy (Theorem~\ref{thm:redundancy}): the sum dial determines the label by Vieta's formulas, the gap dial by Vieta's formulas plus reality, and the synergy equals the lower wall.
\item Field model equals exponent model (Theorem~\ref{thm:model}): the field hint value is $h(6)$.
\item Values, order and walls of the hint map (Section~\ref{sec:hintmap}).
\item The CRT defect law (Theorem~\ref{thm:crt}) and strict superadditivity (Corollary~\ref{cor:strict}).
\item A totient closed form for $\delta$ and multiplicativity of $\sum_{d\mid n}\varphi(d)^2$ (Section~\ref{sec:totient}).
\end{enumerate}
All entropies are Shannon entropies in bits of functions of a uniformly distributed element of a finite set. They are exact real numbers computed from fibre counts.

\section{Preliminaries}

\subsection{Counting entropy}
For a finite non-empty set $S$ with the uniform distribution and a map $F:S\to A$,
\[
H(F)=-\sum_{a\in F(S)}\frac{|F^{-1}(a)|}{|S|}\log_2\frac{|F^{-1}(a)|}{|S|}.
\]
We write $H(F,G)=H((F,G))$, $H(F\mid G)=H(F,G)-H(G)$ and $I(F;G)=H(F)-H(F\mid G)$. If $G$ determines $F$, then $I(F;G)=H(F)$. If all fibres of $G$ have at most $k$ elements, then $H(F\mid G)\le\log_2 k$.

\subsection{Splitting types in cyclic fields of prime conductor}
Let $f$ be an odd prime, $g$ a primitive root mod $f$, and $\ind(u)\in\Z/(f-1)$ the discrete logarithm of $u\in(\Z/f)^\times$. For $n\mid f-1$ let $K_n\subseteq\Q(\zeta_f)$ be the unique subfield of degree $n$, so $\mathrm{Gal}(K_n/\Q)\cong\Z/n$. A prime $p\neq f$ has Frobenius $\ind(p)\bmod n$, and residue degree
\[
f_{K_n}(p)=T_n(\ind(p)),\qquad T_n(a):=\ord_{\Z/n}(a)=\frac{n}{\gcd(a,n)}.
\]
For $f=13$, $n=6$ we have $K_6=\Q(\zeta_{13})^+$, and the residue degree of $p$ is the order of $p$ in $(\Z/13)^\times/\{\pm1\}$. In particular
\begin{equation}\label{eq:real}
f_{K_6}(u)=f_{K_6}(-u)\qquad(u\in(\Z/13)^\times).
\end{equation}

\subsection{The cyclic type channel}
\begin{definition}[Cyclic type channel]
For $n\ge1$ let $B_n=(\Z/n)^2$ with the uniform distribution. For $(a,b)\in B_n$ put $L_n(a,b)=\{T_n(a),T_n(b)\}$ (an unordered pair) and $\Pi_n(a,b)=a+b\bmod n$.
\end{definition}
If $p\equiv g^a$ and $q\equiv g^b$, then $pq\equiv g^{a+b}$, so $\Pi_n$ is the exponent of $N$.

\begin{definition}[Hint map]
$h(n):=I(L_n;\mathrm{id})-I(L_n;\Pi_n)=H(L_n\mid\Pi_n)$.
\end{definition}

\begin{definition}[Auxiliary quantities]
The pair entropy $P(n)=H(L_n)$; the product information $J(n)=I(L_n;\Pi_n)$, so that $h=P-J$; the type entropy $\tau(n)=H(T_n(a))$ for $a$ uniform; and the distinctness probability $\delta(n)=\Pr_{B_n}[T_n(a)\neq T_n(b)]$.
\end{definition}

\section{The round-31 battery over \texorpdfstring{$\Q(\zeta_{13})^+$}{Q(zeta13)+}}

The population is $\Omega=(\Z/13)^\times\times(\Z/13)^\times$ ($144$ elements), with the uniform distribution. The label is $\Lambda(u,v)=\{f_{K_6}(u),f_{K_6}(v)\}$, and the views are $N=uv$, $s=u+v$, $d=u-v$ (mod $13$). Since $2$ is invertible, $(s,d)$ determines $(u,v)$. Define
\[
\hint=I(\Lambda;u,v)-I(\Lambda;N),\quad \mathrm{sumHint}=I(\Lambda;N,s)-I(\Lambda;N),\quad \mathrm{gapHint}=I(\Lambda;N,d)-I(\Lambda;N),
\]
and $\mathrm{synergy}=\hint-\mathrm{sumHint}-\mathrm{gapHint}$.

\begin{lemma}[Fibre counts]\label{lem:fibres}
Among the $144$ pairs: (a) the ten label classes have sizes $4,8,16,16,4,16,16,16,16,32$; (b) the classes of $(\Lambda,N)$ are twelve classes of size $2$, twenty-six of size $4$ and two of size $8$; (c) $N$ takes each of its $12$ values exactly $12$ times.
\end{lemma}
\begin{proof}[Proof sketch]
The exponent $\ind(u)\bmod 6$ is uniform on $\Z/6$, with two units per class. The types $1,2,3,6$ occur with probabilities $\tfrac16,\tfrac16,\tfrac13,\tfrac13$ (from $a=0$; $a=3$; $a=2,4$; $a=1,5$). Multiplying out unordered pairs gives (a). Parts (b) and (c) follow by enumeration.
\end{proof}

\begin{theorem}[Exact round-31 table]\label{thm:table}
\[
H(\Lambda)=I(\Lambda;s,d)=2\log_2 3-\tfrac1{18}\approx3.11437,\quad I(\Lambda;N)=\log_2 3-\tfrac19\approx1.47385,\quad \hint=\log_2 3+\tfrac1{18}\approx1.64052.
\]
The reported value $1.6407$ exceeds the exact hint by more than $10^{-4}$, and the reported $3.1110$ falls below the exact joint value by more than $3\cdot10^{-3}$.
\end{theorem}
\begin{proof}
Write $\ell=\log_2 3$. By Lemma~\ref{lem:fibres}(b),
\[
H(\Lambda,N)=\tfrac{24}{144}(3+2\ell)+\tfrac{104}{144}(2+2\ell)+\tfrac{16}{144}(1+2\ell)=\tfrac{37}{18}+2\ell,
\]
and $H(N)=\log_2 12=2+\ell$, so $H(\Lambda\mid N)=\ell+\tfrac1{18}$. The factor view determines $\Lambda$, so $\hint=H(\Lambda\mid N)$. The value of $H(\Lambda)$ follows from (a), and then $I(\Lambda;N)=H(\Lambda)-H(\Lambda\mid N)$. The numerical claims follow from $1.58496<\log_2 3<1.58497$.
\end{proof}

\begin{theorem}[Field model equals exponent model]\label{thm:model}
$I(\Lambda;N)=J(6)$, $H(\Lambda)=P(6)$, and $\hint=h(6)$.
\end{theorem}
\begin{proof}[Proof sketch]
The discrete logarithm reduced mod $6$ maps $\Omega$ onto $B_6$, with every fibre of size $4$. $\Lambda$ factors as $L_6$, and $N$ corresponds to $\Pi_6$ refined only by a coordinate that is independent of the label. The closed forms of both sides agree.
\end{proof}

\begin{lemma}[Vieta for the two dials]\label{lem:vieta}
Let $R$ be an integral domain and $pq=p'q'$. If $p+q=p'+q'$, then $(p',q')\in\{(p,q),(q,p)\}$. If $p-q=p'-q'$, then $(p',q')\in\{(p,q),(-q,-p)\}$.
\end{lemma}
\begin{proof}
In the first case $(p'-p)(p'-q)=p'^2-(p+q)p'+pq=0$. In the second case $(p'-p)(p'+q)=p'^2-(p-q)p'-pq=0$.
\end{proof}

\begin{theorem}[Maximal redundancy; walls clean]\label{thm:redundancy}
Over $\Q(\zeta_{13})^+$: (1) $(N,s)$ and $(N,d)$ each determine $\Lambda$; (2) $\mathrm{sumHint}=\mathrm{gapHint}=\hint=\log_2 3+\tfrac1{18}$; (3) $\mathrm{synergy}=-(\log_2 3+\tfrac1{18})=-\min(\mathrm{sumHint},\mathrm{gapHint})$; (4) $\mathrm{synergy}<1$ and $0<\hint<H(\Lambda)$.
\end{theorem}
\begin{proof}
(1) By Lemma~\ref{lem:vieta} over $\F_{13}$, pairs with equal $(N,s)$ agree up to swap, and $\Lambda$ is swap-invariant. Pairs with equal $(N,d)$ agree up to $(u,v)\mapsto(-v,-u)$, which preserves $\Lambda$ by \eqref{eq:real}. (2) Hence $I(\Lambda;N,s)=I(\Lambda;N,d)=H(\Lambda)$, and each conditional hint equals $H(\Lambda\mid N)$. (3) and (4) are arithmetic. For the upper wall in general: given $(N,s)$ the pair is known up to order, so $d$ is known up to sign and carries at most one further bit.
\end{proof}

\begin{proposition}[Sum dial without the product]
$I(\Lambda;s)=2\log_2 3+\tfrac{29}{36}-\tfrac{11}{12}\log_2 11\approx0.80434$.
\end{proposition}
\begin{proof}[Proof sketch]
$s=0$ is attained by the $12$ pairs $(u,-u)$, and each non-zero value by $11$ pairs. The classes of $(\Lambda,s)$ are eight of size $1$, fifty of size $2$, four of size $3$ and six of size $4$. So $H(s)=4+2\ell-\frac{132\log_2 11+12(2+\ell)}{144}$ and $H(\Lambda,s)=4+2\ell-\frac{148+12\ell}{144}$. Then combine $I=H(\Lambda)+H(s)-H(\Lambda,s)$.
\end{proof}

\section{The hint map: values, order, walls}\label{sec:hintmap}

\begin{theorem}[First values]\label{thm:values}
\[
h(2)=\tfrac12,\ h(3)=\log_2 3-\tfrac23,\ h(4)=\tfrac98,\ h(5)=\log_2 5-\tfrac{12}{25}\log_2 3-\tfrac{16}{25},\ h(6)=\log_2 3+\tfrac1{18}.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Fibre counts in $B_n$. For $n=2$, the fibre $\Pi=0$ contains $(0,0),(1,1)$ with labels $\{1,1\},\{2,2\}$, contributing $1$ bit. The fibre $\Pi=1$ has the single label $\{1,2\}$, contributing $0$. The average is $\tfrac12$.
\end{proof}

\begin{theorem}[Order: the hint extends beyond degree five]
$h(2)<h(3)<h(5)<h(4)<h(6)$. In particular $h(6)>h(n)$ for $n\in\{2,3,4,5\}$, and $h$ is not monotone.
\end{theorem}
\begin{proof}
The values are $0.5$, $0.91830$, $0.92115$, $1.125$ and $1.64052$. Rigorous brackets on $\log_2 3$ and $\log_2 5$ certify each inequality.
\end{proof}

\begin{theorem}[Walls]
For all $n\ge1$: $0\le h(n)\le P(n)$ and $h(n)\le\log_2 n$.
\end{theorem}
\begin{proof}
Each fibre $\{a+b\equiv c\}$ has exactly $n$ elements.
\end{proof}

\section{The CRT defect law}

\begin{theorem}[Unordered-pair entropy law]\label{thm:unordered}
Let $S$ be finite and non-empty, $\beta$ linearly ordered, and $g:S\to\beta$. For $(x,y)$ uniform on $S\times S$,
\[
H(\{g(x),g(y)\})=H(g(x),g(y))-\Pr[g(x)\neq g(y)].
\]
\end{theorem}
\begin{proof}
Encode unordered pairs as $(\min,\max)$. The unordered fibre through $(x_0,y_0)$ is the union of the ordered fibres of $(g(x_0),g(y_0))$ and $(g(y_0),g(x_0))$. The swap $(x,y)\mapsto(y,x)$ is a bijection between them. If $g(x_0)\neq g(y_0)$ they are disjoint, so the unordered fibre is twice as large; otherwise they coincide. Hence $\log_2|\text{unordered fibre}|=\log_2|\text{ordered fibre}|+\mathbf 1[g(x_0)\neq g(y_0)]$ pointwise. Averaging gives the claim.
\end{proof}

\begin{corollary}[Label entropy]\label{cor:label}
$P(n)=2\tau(n)-\delta(n)$.
\end{corollary}

Let $m,n$ be coprime. The CRT bijection $\Z/mn\to\Z/m\times\Z/n$ preserves uniformity and addition.

\begin{lemma}[Orders multiply]\label{lem:orders}
$T_{mn}(a)=T_m(a\bmod m)\,T_n(a\bmod n)$. Hence $T_{mn}(a)=T_{mn}(b)$ if and only if $T_m(a)=T_m(b)$ and $T_n(a)=T_n(b)$.
\end{lemma}
\begin{proof}
The order in a product is the lcm of the component orders. These divide the coprime numbers $m$ and $n$, so the lcm is their product. Moreover $d_1d_2$ determines $d_1=\gcd(d_1d_2,m)$ and $d_2=\gcd(d_1d_2,n)$.
\end{proof}

\begin{corollary}\label{cor:crt}
(a) $\tau(mn)=\tau(m)+\tau(n)$. (b) $1-\delta(mn)=(1-\delta(m))(1-\delta(n))$; equivalently, the equal-type counts multiply.
\end{corollary}

\begin{lemma}[Product information is additive]\label{lem:J}
$J(mn)=J(m)+J(n)$ for coprime $m,n$.
\end{lemma}
\begin{proof}[Proof sketch]
Let $\vec L_n=(T_n(a),T_n(b))$. Then
\[
I(\vec L_n;\Pi_n)-I(L_n;\Pi_n)=H(\vec L_n\mid L_n)-H(\vec L_n\mid L_n,\Pi_n)=\delta(n)-\delta(n)=0,
\]
because the swap $(a,b)\mapsto(b,a)$ preserves $L_n$ and $\Pi_n$ and flips the order. So the order bit is a fair coin on the off-diagonal, even given $\Pi_n$. Under the CRT, $(\vec L_{mn},\Pi_{mn})$ corresponds bijectively to $((\vec L_m,\Pi_m),(\vec L_n,\Pi_n))$, whose two components are independent. Mutual information adds over independent products.
\end{proof}

\begin{theorem}[CRT Defect Law]\label{thm:crt}
For coprime positive integers $m,n$,
\[
\boxed{\;h(mn)=h(m)+h(n)+\delta(m)\,\delta(n).\;}
\]
\end{theorem}
\begin{proof}
By Corollary~\ref{cor:label}, $h(k)=2\tau(k)-\delta(k)-J(k)$. By Corollary~\ref{cor:crt}(a) and Lemma~\ref{lem:J}, the terms $2\tau$ and $J$ are additive. So $h(mn)-h(m)-h(n)=\delta(m)+\delta(n)-\delta(mn)$, which equals $\delta(m)\delta(n)$ by Corollary~\ref{cor:crt}(b).
\end{proof}

\begin{remark}
$\delta(m)\delta(n)$ is the probability that the pair is \emph{doubly distinct}, that is, distinct in type modulo $m$ and modulo $n$. On that event the composite label forgets one bit of order, while the two component labels would together forget two. The product channel and the type entropy are exactly additive, so the whole defect comes from the unordered label.
\end{remark}

\begin{corollary}[Strict superadditivity]\label{cor:strict}
For coprime $m,n$, $h(mn)\ge h(m)+h(n)$, with strict inequality if $m,n\ge2$.
\end{corollary}
\begin{proof}
For $k\ge2$ the exponents $0$ and $1$ have types $1$ and $k$, so $\delta(k)\ge2/k^2>0$.
\end{proof}

\begin{table}[h]
\centering
\begin{tabular}{cccccc}
\toprule
$mn$ & $(m,n)$ & $\delta(m)$ & $\delta(n)$ & defect & $h(mn)$\\
\midrule
$6$ & $(2,3)$ & $1/2$ & $4/9$ & $2/9$ & $1.64052$\\
$10$ & $(2,5)$ & $1/2$ & $8/25$ & $4/25$ & $1.58115$\\
$12$ & $(4,3)$ & $5/8$ & $4/9$ & $5/18$ & $2.32107$\\
$15$ & $(3,5)$ & $4/9$ & $8/25$ & $32/225$ & $1.98166$\\
\bottomrule
\end{tabular}
\caption{Instances of the CRT defect law.}
\end{table}

\section{Arithmetic form of the defect}\label{sec:totient}

\begin{theorem}[Totient closed form]
$\#\{(a,b)\in B_n:T_n(a)=T_n(b)\}=\sum_{d\mid n}\varphi(d)^2$, and so $\delta(n)=1-n^{-2}\sum_{d\mid n}\varphi(d)^2$.
\end{theorem}
\begin{proof}
Collisions of $g$ in $S\times S$ number $\sum_v|g^{-1}(v)|^2$, and $\Z/n$ has exactly $\varphi(d)$ elements of order $d$ for each $d\mid n$.
\end{proof}

\begin{corollary}
$\Sigma(n)=\sum_{d\mid n}\varphi(d)^2$ is multiplicative: $\Sigma(mn)=\Sigma(m)\Sigma(n)$ for coprime $m,n$. Consequently
\[
h(mn)=h(m)+h(n)+\Bigl(1-\tfrac{\Sigma(m)}{m^2}\Bigr)\Bigl(1-\tfrac{\Sigma(n)}{n^2}\Bigr).
\]
\end{corollary}

\begin{example}
$\Sigma(6)=1+1+4+4=10$, so $\delta(6)=\tfrac{13}{18}$. $\Sigma(12)=30$, so $\delta(12)=\tfrac{19}{24}$.
\end{example}

\section{Algorithms}
\textbf{A (exact fibre counting).} For each $c\in\Z/n$, tally the labels of $(a,c-a)$ and add $\frac1n H(\text{tally})$. Cost $O(n^2)$.

\textbf{B (CRT reduction).} Factor $n=\prod p_i^{e_i}$, compute $(h,\,1-\delta)$ at each prime power, and fold with
$(h,\bar\delta)\otimes(h',\bar\delta')=(h+h'+(1-\bar\delta)(1-\bar\delta'),\ \bar\delta\bar\delta')$.
Cost $O(\max_i p_i^{2e_i})$.

\textbf{C (field battery).} Enumerate the $(f-1)^2$ unit pairs, label them by residue degree using discrete logarithms, and compute the mutual informations with $N$, $(s,d)$, $(N,s)$ and $(N,d)$.

\section{Discussion}
The product channel and the type entropy are exactly CRT-additive. The superadditivity of $h$ comes entirely from the order-forgetting correction. This is the same mechanism as for the entropy of two indistinguishable particles, where symmetrisation costs one bit exactly when the states differ. With exact closed forms, the verdict ``walls clean'' becomes a precise statement: the redundancy floor is attained with equality, for an algebraic reason. Theorem~\ref{thm:redundancy} uses reality essentially. Numerically, in the imaginary degree-$4$ subfield of $\Q(\zeta_{13})$ the gap hint is $0.5$ bits against a hint of $1.125$; this is a computational observation, not a theorem. Applications include exact calibration of how much splitting information about the factors of a modulus is hidden beyond public residues (at most $\log_2 n$ bits), a fully solvable test case for information-decomposition methods, and an entropy-based proof of an arithmetic multiplicativity.

\section{Future directions}
\begin{conjecture}[Prime rungs]
For every prime $q$, $h(q)=\frac{q-1}{q}H_b(\frac2q)+\frac1qH_b(\frac1q)$, where $H_b$ is the binary entropy; in particular $h(q)\to0$. Only the types $1$ and $q$ occur, and in each fibre $\Pi=c\neq0$ only $(0,c)$ and $(c,0)$ contain type $1$. Numerically the formula agrees to twelve digits for $q\le19$.
\end{conjecture}
\begin{conjecture}[Field--exponent transfer]
For every prime $f$ and $n\mid f-1$, the battery over the degree-$n$ subfield of $\Q(\zeta_f)$ has hint value $h(n)$. This has been checked numerically for $f\in\{7,11,13,17\}$, and proved for $f=13$, $n=6$.
\end{conjecture}
\begin{conjecture}[Reality criterion]
$\mathrm{gapHint}=\hint$ if and only if the labels are invariant under $u\mapsto-u$; for subfields of $\Q(\zeta_f)$, if and only if the field is real.
\end{conjecture}
\begin{conjecture}[Powers of two]
Computed values for $k\le6$ fit $h(2^k)=2(1-2^{-k})^2$.
\end{conjecture}

\section{Conclusion}
The degree-six hint value is exactly $\log_2 3+\tfrac1{18}$ bits. The two single dials are perfectly redundant, by Vieta's formulas and reality. The field battery equals the abstract channel. On coprime composites the hint map obeys $h(mn)=h(m)+h(n)+\delta(m)\delta(n)$, with the defect given explicitly by Euler's totient.

\end{document}

