from collections import Counter
from math import gcd, log2


def hint_map_exact(n: int) -> float:
    types = [n // gcd(a, n) for a in range(n)]
    h = 0.0
    for c in range(n):
        tally: Counter[tuple[int, int]] = Counter()
        for a in range(n):
            s, t = types[a], types[(c - a) % n]
            tally[(min(s, t), max(s, t))] += 1
        h -= sum(k / n * log2(k / n) for k in tally.values()) / n
    return h


def phi(n: int) -> int:
    result, m, p = n, n, 2
    while p * p <= m:
        if m % p == 0:
            while m % p == 0:
                m //= p
            result -= result // p
        p += 1
    if m > 1:
        result -= result // m
    return result


def equal_type_fraction(n: int) -> float:
    """1 - delta(n) = (sum_{d|n} phi(d)^2) / n^2."""
    return sum(phi(d) ** 2 for d in range(1, n + 1) if n % d == 0) / n**2


def prime_power_factors(n: int) -> list[int]:
    out, p = [], 2
    while p * p <= n:
        if n % p == 0:
            q = 1
            while n % p == 0:
                n //= p
                q *= p
            out.append(q)
        p += 1
    if n > 1:
        out.append(n)
    return out


def hint_map_crt(n: int) -> float:
    """Fold prime-power rungs with the CRT defect law
    h(mn) = h(m) + h(n) + delta(m) delta(n)."""
    h, eq = 0.0, 1.0                     # the trivial rung n = 1: h = 0, 1 - delta = 1
    for q in prime_power_factors(n):
        hq, eqq = hint_map_exact(q), equal_type_fraction(q)
        h = h + hq + (1 - eq) * (1 - eqq)
        eq = eq * eqq
    return h


if __name__ == "__main__":
    for n in (6, 10, 12, 15, 30, 60, 210):
        print(n, round(hint_map_crt(n), 9), round(hint_map_exact(n), 9))

from collections import Counter
from math import log2


def entropy(counts: Counter, total: int) -> float:
    return -sum(c / total * log2(c / total) for c in counts.values())


def primitive_root(f: int) -> int:
    return next(g for g in range(2, f)
                if len({pow(g, k, f) for k in range(1, f)}) == f - 1)


def field_battery(f: int, n: int) -> dict[str, float]:
    """Round-31 information battery over the degree-n subfield of Q(zeta_f)."""
    from math import gcd
    g = primitive_root(f)
    ind = {pow(g, k, f): k for k in range(f - 1)}
    deg = {u: n // gcd(ind[u] % n, n) for u in ind}          # residue degree
    pop = [(u, v) for u in ind for v in ind]
    lab = lambda x: tuple(sorted((deg[x[0]], deg[x[1]])))
    views = {
        "N": lambda x: x[0] * x[1] % f,
        "pq": lambda x: x,
        "Ns": lambda x: (x[0] * x[1] % f, (x[0] + x[1]) % f),
        "Nd": lambda x: (x[0] * x[1] % f, (x[0] - x[1]) % f),
    }
    tot = len(pop)
    HL = entropy(Counter(map(lab, pop)), tot)
    I = {k: HL + entropy(Counter(map(v, pop)), tot)
         - entropy(Counter((lab(x), v(x)) for x in pop), tot) for k, v in views.items()}
    hint, sh, gh = I["pq"] - I["N"], I["Ns"] - I["N"], I["Nd"] - I["N"]
    return {"H": HL, "I_N": I["N"], "hint": hint, "sumHint": sh, "gapHint": gh,
            "synergy": hint - sh - gh}


if __name__ == "__main__":
    print(field_battery(13, 6))   # hint = log2 3 + 1/18 = 1.640518...

